test_stated_count_still_correlates_the_container_and_the_key[class Glyph { constructor(public key:string) {} }
class Pool {
 pool:{[key:string]:Glyph}={};
 other:{[key:string]:Glyph}={};
 get(key:string):Glyph {
let result = this.other[key];
if (result === undefined) {
result = new Glyph(key);
this.pool[key] = result;
}
return result;
}}]

